import React, { useState } from 'react';

const QuizPage = () => {
        const [formData, setFormData] = useState({
                subject: "",
                exam: "",
                difficultyLevels: [],
                classYear:"",
                topics:"",
                name:"",
                quizMode:"",
                addHints:false,
                adaptiveDifficulty:false,
                answerExplanation:false,
                breakIntoSubtopics:false,
        });

        // A function to handle input changes for both fields
        const handleChange = (e) => {
                const { name, value, type, checked } = e.target;
                setFormData((prevData) => ({
                        ...prevData,
                        [name]: type === "checkbox" ? checked : value,
                }));
        };

        const handleDifficultyChange = (e) => {
                const { value, checked } = e.target;
                setFormData((prevData) => ({
                        ...prevData,
                        difficultyLevels: checked ? 
                                [...prevData.difficultyLevels, value] : prevData.difficultyLevels.filter((level) => level !== value),
                }));
        };

        const handleSubmit = (event) => {
                e.preventDefault();
                console.log(formData);
        };


        return (
                <div>
                        <form onSubmit={handleSubmit}>

                                <h3>What should we call you?</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. ABC XYZ"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                />

                                <h3>Enter subject</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. Maths, Physics"
                                        name="subject"
                                        value={formData.subject}
                                        onChange={handleChange}
                                />

                                <h3>Exam Type</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. MidTerm, JEE"
                                        name="exam"
                                        value={formData.exam}
                                        onChange={handleChange}
                                />

                                <label className="block font-semibold">Select Difficulty Levels</label>
                                <div>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Easy"
                                                        checked={formData.difficultyLevels.includes('Easy')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Easy
                                        </label>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Medium"
                                                        checked={formData.difficultyLevels.includes('Medium')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Medium
                                        </label>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Hard"
                                                        checked={formData.difficultyLevels.includes('Hard')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Hard
                                        </label>
                                </div>

                                <h3>Class / College Year</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. class 11, 3rd Year"
                                        name="classYear"
                                        value={formData.classYear}
                                        onChange={handleChange}
                                />

                                <h3>Enter topics</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. Photosynthesis, Surface Tension"
                                        name="topics"
                                        value={formData.topics}
                                        onChange={handleChange}
                                />

                                <h3>Additional Features</h3>

                                <label>Add Hints</label>
                                <input
                                        type="checkbox"
                                        name="addHints"
                                        checked={formData.addHints}
                                        onChange={handleChange}
                                />

                                <label>Adaptive Difficulty</label>
                                <input
                                        type="checkbox"
                                        name="adaptiveDifficulty"
                                        checked={formData.adaptiveDifficulty}
                                        onChange={handleChange}
                                />

                                <label>Include Answer Explanation</label>
                                <input
                                        type="checkbox"
                                        name="answerExplanation"
                                        checked={formData.answerExplanation}
                                        onChange={handleChange}
                                />

                                <label>Break into Subtopics</label>
                                <input
                                        type="checkbox"
                                        name="breakIntoSubtopics"
                                        checked={formData.breakIntoSubtopics}
                                        onChange={handleChange}
                                />

                                <div className="mb-4 text-center">
                                        <button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded-lg">
                                                Create Quiz
                                        </button>
                                </div>

                        </form>
                </div>
        );
};

export default QuizPage;
